export const BODY: string = "\n<p>JPG کو PNG میں بدلنا ایک سادہ تبدیلی لگتی ہے، مگر اس کے پیچھے اہم سچائی ہے: یہ تبدیلی تصویر کو بہتر نہیں بناتی، صرف فائل کو بڑا کر دیتی ہے۔</p>\n<p>اس کے باوجود کچھ کاموں کے لیے یہ تبدیلی ضروری ہے، جیسے ایڈیٹنگ، پرنٹ اور پیشکش۔ فرق یہ جاننا ہے کہ کب یہ تبدیلی مفید ہے اور کب وقت ضائع کرنا ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ تبدیلی میں کیا ہوتا ہے، فائل بڑی کیوں ہوتی ہے، شفافیت کا فریب کیا ہے، اور درست ایڈیٹنگ کا طریقہ کیا ہے۔ تبدیل کرنے کے لیے <a href=\"/ur/jpg-ko-png-mein-convert-karein/\">JPG ٹو PNG</a> استعمال کریں۔</p>\n<h2 id=\"what-happens-in-conversion\">JPG PNG بننے پر کیا ہوتا ہے؟</h2>\n<p>JPG کے پکسلز کو PNG فارمیٹ میں دوبارہ لکھا جاتا ہے، بغیر کسی نئی تفصیل کے۔ جو تفصیل JPG نے کھو دی تھی، وہ واپس نہیں آتی۔</p>\n<p>تبدیلی کے بعد تصویر ویسی ہی نظر آتی ہے، جیسی پہلے تھی۔ صرف فائل کا فارمیٹ اور سائز بدلتا ہے، تصویر کا معیار نہیں۔</p>\n<p>یہ تبدیلی اس وقت مفید ہے جب آپ کو PNG کی خصوصیت چاہیے، جیسے بغیر نقصان کے محفوظ کرنا۔ معیار بہتر کرنے کے لیے یہ تبدیلی بیکار ہے۔</p>\n<h2 id=\"why-files-get-bigger\">PNG فائلیں اتنی بڑی کیوں ہو جاتی ہیں؟</h2>\n<p>PNG بغیر نقصان کے کمپریس کرتا ہے، اس لیے وہ JPG کی طرح تفصیل نہیں پھینکتا۔ ایک 500KB JPG تصویر PNG میں 3MB یا اس سے زیادہ ہو سکتی ہے۔</p>\n<p>فرق تصویر کی قسم پر منحصر ہے: سادہ گرافکس PNG میں چھوٹے رہتے ہیں، مگر فوٹو بہت بڑے ہو جاتے ہیں۔ فوٹو میں ہر پکسل الگ رنگ رکھتا ہے، جسے PNG محفوظ کرتا ہے۔</p>\n<p>بڑی فائل کا مطلب ہے سست اپ لوڈ اور زیادہ جگہ۔ فوٹو کو PNG میں بدلنے سے پہلے سوچیں کہ کیا فائدہ ہے۔</p>\n<h2 id=\"when-it-is-useful\">JPG ٹو PNG کب واقعی مفید ہے؟</h2>\n<p>جب آپ کو تصویر کو بار بار ایڈٹ کرنا ہو تو PNG مفید ہے، کیونکہ ہر محفوظ کرنے پر معیار نہیں گرتا۔ ایڈیٹنگ کے دوران PNG ماسٹر کے طور پر کام کرتا ہے۔</p>\n<p>پرنٹ اور پیشکش کے لیے بھی PNG اچھا ہے، کیونکہ وہ متن اور لکیریں تیز رکھتا ہے۔ سافٹ ویئر جو صرف PNG لیتا ہے، اس کے لیے بھی یہ تبدیلی ضروری ہے۔</p>\n<p>مختصر یہ کہ PNG اس وقت چنیں جب آپ کو بغیر نقصان والا فارمیٹ چاہیے، نہ کہ جب آپ کو بہتر تصویر چاہیے۔</p>\n<h2 id=\"when-it-is-pointless\">JPG ٹو PNG کب بے کار ہے؟</h2>\n<p>ویب سائٹ پر ڈالنے کے لیے JPG کو PNG میں بدلنا بے کار ہے، کیونکہ فائل بڑی ہو جاتی ہے اور تصویر ویسی ہی رہتی ہے۔ ویب کے لیے JPG یا WebP بہتر ہیں۔</p>\n<p>ای میل میں بھیجنے کے لیے بھی یہ تبدیلی بے کار ہے، کیونکہ بڑی فائل بھیجنا مشکل ہوتا ہے۔ وصول کرنے والے کو کوئی فرق نظر نہیں آئے گا۔</p>\n<p>معیار بہتر کرنے کے لیے یہ تبدیلی ہمیشہ بے کار ہے۔ کھوئی ہوئی تفصیل کبھی واپس نہیں آتی، چاہے فارمیٹ کچھ بھی ہو۔</p>\n<h2 id=\"no-quality-slider\">معیار کا سلائیڈر کیوں نہیں ہے</h2>\n<p>PNG میں معیار کا سلائیڈر نہیں ہوتا، کیونکہ وہ بغیر نقصان کے محفوظ کرتا ہے۔ ہر پکسل بالکل محفوظ رہتا ہے، اس لیے معیار چننے کی ضرورت نہیں۔</p>\n<p>سلائیڈر نہ ہونے کا مطلب یہ نہیں کہ فائل چھوٹی ہوگی۔ PNG ہمیشہ بڑی فائل بناتا ہے، کیونکہ وہ کچھ پھینکتا نہیں۔</p>\n<p>اگر فائل چھوٹی چاہیے تو PNG غلط انتخاب ہے۔ JPG یا WebP چنیں، جہاں معیار کا سلائیڈر فائل کو قابو کرتا ہے۔</p>\n<h2 id=\"transparency-myth\">شفافیت کا فریب</h2>\n<p>JPG کو PNG میں بدلنے سے شفافیت نہیں بنتی۔ JPG میں شفاف حصہ ہوتا ہی نہیں، اس لیے سفید پس منظر سفید ہی رہتا ہے۔</p>\n<p>شفافیت بنانے کے لیے پس منظر کو ہٹانا پڑتا ہے، جو الگ کام ہے۔ صرف فارمیٹ بدلنے سے پس منظر شفاف نہیں ہوتا۔</p>\n<p>اگر آپ کو شفاف لوگو چاہیے تو اصل ڈیزائن فائل سے شفاف PNG بنائیں۔ JPG سے شفافیت کی توقع رکھنا غلطی ہے۔</p>\n<h2 id=\"renaming-is-not-converting\">نام بدلنا تبدیل کرنا نہیں ہے</h2>\n<p>فائل کا نام .jpg سے .png بدلنے سے فارمیٹ نہیں بدلتا، صرف نام بدلتا ہے۔ اندر کا ڈیٹا JPG ہی رہتا ہے، اور پروگرام اسے کھولنے میں الجھ جاتا ہے۔</p>\n<p>درست تبدیلی کے لیے کنورٹر استعمال کریں، جو پکسلز کو دوبارہ لکھتا ہے۔ نام بدلنا فائل کو خراب کرتا ہے، تبدیل نہیں کرتا۔</p>\n<p>اگر آپ نے نام بدل کر فائل خراب کر دی ہو تو اصل نام واپس لگائیں اور کنورٹر سے تبدیل کریں۔</p>\n<h2 id=\"batch-converting\">JPG کی بیچ تبدیلی</h2>\n<p>بیچ میں بہت سی JPG تصویریں ایک ساتھ PNG میں بدلی جا سکتی ہیں۔ پوری کیٹلاگ یا البم کے لیے یہ بہت وقت بچاتا ہے۔</p>\n<p>بیچ بدلنے سے پہلے ایک تصویر آزمائیں اور فائل کا سائز دیکھیں۔ اگر ایک تصویر پانچ گنا بڑی ہو تو پوری بیچ بہت بڑی ہو جائے گی۔</p>\n<p>بیچ کا نتیجہ ZIP میں ملتا ہے، جس میں نام وہی رہتے ہیں۔ ZIP کھولنے کے بعد فائلوں کو جانچ لیں۔</p>\n<h2 id=\"cmyk-and-colour\">CMYK JPG اور رنگ کی تبدیلی</h2>\n<p>پرنٹ کے لیے بنے CMYK JPG کو PNG میں بدلنے پر رنگ بدل سکتے ہیں، کیونکہ PNG RGB رنگ استعمال کرتا ہے۔ سرخ رنگ نارنجی اور نیلا رنگ جامنی لگ سکتا ہے۔</p>\n<p>CMYK تصویر کو بدلنے سے پہلے اسے RGB میں بدلیں اور رنگ جانچیں۔ پرنٹ کے لیے CMYK رکھیں، اسکرین کے لیے RGB چنیں۔</p>\n<p>رنگ کی تبدیلی سے بچنے کے لیے اصل RGB فائل تلاش کریں۔ CMYK سے RGB تبدیلی ہمیشہ رنگ بدلتی ہے۔</p>\n<h2 id=\"editing-workflow\">سمجھدار ایڈیٹنگ کا طریقہ</h2>\n<p>ایڈیٹنگ کا درست طریقہ یہ ہے: JPG کو PNG میں بدلیں، PNG پر ایڈٹ کریں، اور آخری نتیجہ JPG یا WebP میں برآمد کریں۔ اس سے ایڈیٹنگ کے دوران معیار نہیں گرتا۔</p>\n<p>PNG ماسٹر کو محفوظ رکھیں اور اس سے ہر نیا نسخہ بنائیں۔ ماسٹر سے بنایا گیا ہر نسخہ صاف ہوتا ہے، جبکہ نقل سے بنایا گیا نسخہ خراب ہوتا ہے۔</p>\n<p>ایڈیٹنگ کے دوران بار بار JPG میں محفوظ نہ کریں، کیونکہ ہر بار معیار گرتا ہے۔ صرف آخر میں JPG بنائیں۔</p>\n<h2 id=\"exif-and-privacy\">EXIF ڈیٹا اور پرائیویسی</h2>\n<p>تبدیلی کے دوران EXIF ڈیٹا اکثر برقرار رہتا ہے، جس میں مقام اور کیمرے کی معلومات ہو سکتی ہیں۔ شیئر کرنے سے پہلے میٹا ڈیٹا جانچیں۔</p>\n<p>اگر تصویر نجی ہو تو میٹا ڈیٹا صاف کر کے تبدیل کریں۔ صاف شدہ فائل میں مقام نہیں ہوتا، اس لیے وہ شیئر کرنے کے لیے محفوظ ہے۔</p>\n<p>میٹا ڈیٹا جانچنے کے لیے ویور استعمال کریں اور صاف کرنے کے لیے الگ ٹول استعمال کریں۔</p>\n<h2 id=\"compatibility\">PNG فائلیں کہاں بہتر کام کرتی ہیں</h2>\n<p>PNG ہر براؤزر، ایڈیٹر اور پرنٹر میں کھلتا ہے۔ یہ سب سے زیادہ مطابقت رکھنے والا بغیر نقصان والا فارمیٹ ہے۔</p>\n<p>پرانا سافٹ ویئر بھی PNG کھولتا ہے، جبکہ WebP یا HEIC نہیں کھولتا۔ مطابقت چاہیے ہو تو PNG محفوظ انتخاب ہے۔</p>\n<p>لیکن ویب کے لیے PNG بھاری ہے، اس لیے مطابقت اور سائز کا توازن دیکھیں۔</p>\n<h2 id=\"png-for-presentations\">پریزنٹیشن کے لیے PNG</h2>\n<p>پریزنٹیشن میں PNG اچھا ہے، کیونکہ وہ متن اور گرافکس کو تیز رکھتا ہے۔ سلائیڈ پر لگا چارٹ PNG میں صاف نظر آتا ہے۔</p>\n<p>پریزنٹیشن کی فائل بڑی ہو سکتی ہے، مگر سلائیڈ کا معیار اہم ہے۔ فوٹو سلائیڈ کے لیے JPG بھی چل جاتا ہے، مگر چارٹ کے لیے PNG ضروری ہے۔</p>\n<p>پریزنٹیشن میں PNG تصویر کو درست سائز میں رکھیں، تاکہ فائل بہت بڑی نہ ہو۔</p>\n<h2 id=\"png-for-social-graphics\">سوشل میڈیا گرافکس کے لیے PNG</h2>\n<p>سوشل میڈیا گرافکس، جیسے اقتباس والی تصویر یا اعلان، PNG میں تیز رہتے ہیں۔ متن PNG میں صاف پڑھا جاتا ہے، جبکہ JPG میں دھندلا ہو جاتا ہے۔</p>\n<p>لیکن سوشل پلیٹ فارم تصویر کو خود کمپریس کرتے ہیں، اس لیے PNG کا فائدہ کم ہو جاتا ہے۔ پھر بھی اصل گرافکس PNG میں بنانا اچھا ہے۔</p>\n<p>سوشل گرافکس کے لیے PNG ماسٹر رکھیں اور پلیٹ فارم کے لیے JPG نسخہ بنائیں۔</p>\n<h2 id=\"png-for-print-work\">پرنٹ کے کام کے لیے PNG</h2>\n<p>پرنٹ کے لیے PNG اچھا ہے، کیونکہ وہ متن اور لکیریں تیز رکھتا ہے۔ چھوٹے پرنٹ، جیسے کارڈ یا لیبل، PNG میں صاف نکلتے ہیں۔</p>\n<p>بڑے فوٹو پرنٹ کے لیے PNG بہت بڑا ہو جاتا ہے۔ فوٹو پرنٹ کے لیے JPG یا TIFF بہتر ہے، کیونکہ وہ چھوٹی فائل میں اچھا رنگ دیتے ہیں۔</p>\n<p>پرنٹ سے پہلے تصویر کو 300 ڈی پی آئی پر جانچیں، تاکہ پرنٹ دھندلا نہ نکلے۔</p>\n<h2 id=\"storing-png-masters\">PNG ماسٹر محفوظ کرنا</h2>\n<p>PNG ماسٹر کو الگ فولڈر میں محفوظ کریں اور اس پر کبھی براہ راست کام نہ کریں۔ ماسٹر سے ہر نیا نسخہ بنائیں، تاکہ اصل ہمیشہ صاف رہے۔</p>\n<p>ماسٹر کا نام تاریخ اور مقصد سے رکھیں، تاکہ بعد میں تلاش کرنا آسان ہو۔ ایک نقل کلاؤڈ میں بھی رکھیں۔</p>\n<p>PNG ماسٹر بڑے ہوتے ہیں، اس لیے جگہ کا خیال رکھیں۔ صرف اہم تصویروں کا PNG ماسٹر رکھیں، عام تصویروں کا JPG کافی ہے۔</p>\n<h2 id=\"png-for-app-store-screenshots\">ایپ اسٹور اسکرین شاٹ کے لیے PNG</h2>\n<p>ایپ اسٹور اسکرین شاٹ PNG میں مانگتا ہے، کیونکہ وہ متن کو تیز رکھتا ہے۔ اسکرین شاٹ میں ایپ کا نام اور بٹن صاف پڑھے جانے چاہییں۔</p>\n<p>اسکرین شاٹ کو JPG میں بدلنے سے متن دھندلا ہو جاتا ہے اور ایپ غیر پیشہ ورانہ لگتی ہے۔ اس لیے اسٹور کے لیے ہمیشہ PNG استعمال کریں۔</p>\n<p>اسکرین شاٹ کا سائز بھی درست رکھیں: ایپ اسٹور اپنے سائز دیتا ہے، اور غلط سائز مسترد ہو جاتا ہے۔ شفافیت کا فرق <a href=\"/ur/blog/jpg-vs-png-transparency/\">JPG بمقابلہ PNG شفافیت</a> میں اور عملی مراحل <a href=\"/ur/blog/jpg-ko-png-mein-kaise-convert-karein/\">JPG کو PNG میں کیسے بدلیں</a> میں دیکھیں۔ WebP چاہیے ہو تو <a href=\"/ur/jpg-ko-webp-mein-convert-karein/\">JPG ٹو WebP</a> استعمال کریں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"کیا JPG کو PNG میں بدلنے سے میری تصویر تیز ہو جائے گی؟","answer":"نہیں، کھوئی ہوئی تفصیل واپس نہیں آتی۔ PNG صرف وہی بچاتا ہے جو JPG میں باقی ہے، اس لیے تصویر ویسی ہی رہتی ہے، صرف فائل بڑی ہو جاتی ہے۔"},{"question":"میری PNG فائل JPG سے پانچ گنا بڑی کیوں ہے؟","answer":"PNG بغیر نقصان کے کمپریس کرتا ہے، اس لیے وہ JPG کی طرح تفصیل نہیں پھینکتا۔ فوٹو میں ہر پکسل الگ رنگ رکھتا ہے، جسے PNG محفوظ کرتا ہے، اور فائل بڑی ہو جاتی ہے۔"},{"question":"کیا JPG کو PNG میں بدلنے سے تصویر کا سفید پس منظر شفاف ہو جاتا ہے؟","answer":"نہیں، سفید پس منظر سفید ہی رہتا ہے۔ شفافیت بنانے کے لیے پس منظر کو ہٹانا پڑتا ہے، جو الگ کام ہے۔ صرف فارمیٹ بدلنے سے شفافیت نہیں بنتی۔"},{"question":"کیا JPG ٹو PNG تبدیلی اسکین شدہ دستاویزات کے لیے محفوظ ہے؟","answer":"جی ہاں، PNG متن کو تیز رکھتا ہے، اس لیے اسکین شدہ دستاویز کے لیے یہ اچھا ہے۔ لیکن فائل بہت بڑی ہو جاتی ہے، اس لیے صرف اہم دستاویزات کو PNG میں بدلیں۔"},{"question":"کیا میں فون پر JPG کو PNG میں بدل سکتا ہوں؟","answer":"جی ہاں، کنورٹر براؤزر میں چلتا ہے اور فون پر بھی کام کرتا ہے۔ تصویر منتخب کریں، تبدیل کریں اور نتیجہ ڈاؤن لوڈ کریں۔"},{"question":"JPG ٹو PNG کے بجائے JPG ٹو WebP کب چنیں؟","answer":"ویب کے لیے WebP چنیں، کیونکہ وہ PNG سے بہت چھوٹا ہوتا ہے۔ PNG صرف اس وقت چنیں جب بغیر نقصان والا فارمیٹ یا پرانے سافٹ ویئر کی مطابقت چاہیے۔"}];
